<main>
    <section class="section section--gray"><div class="container"><div class="section__title"><h1>Nuestros productos</h1><p class="section__title-text">La gama más completa de software empresarial en México.</p></div></div></section>
    <section class="section"><div class="container"><div class="grid">
        <?php if ($products): ?><?php foreach ($products as $product): ?><article class="card product-card"><div class="product-card__visual"><?php if ($product->imagePath): ?><img src="<?php echo htmlspecialchars($product->imagePath, ENT_QUOTES, 'UTF-8'); ?>" alt="<?php echo htmlspecialchars($product->name, ENT_QUOTES, 'UTF-8'); ?>"><?php endif; ?></div><div class="product-card__info"><h3 class="product-card__title"><?php echo htmlspecialchars($product->name, ENT_QUOTES, 'UTF-8'); ?></h3><p class="product-card__text"><?php echo htmlspecialchars($product->shortDescription, ENT_QUOTES, 'UTF-8'); ?></p><div class="product-card__actions"><a href="product_view.php?id=<?php echo $product->id; ?>" class="btn btn--secondary btn--full">Detalles</a><?php if ($product->pdfPath): ?><a href="<?php echo htmlspecialchars($product->pdfPath, ENT_QUOTES, 'UTF-8'); ?>" target="_blank" rel="noopener" class="btn" title="Descargar ficha"><i class="fas fa-file-pdf"></i></a><?php endif; ?></div></div></article><?php endforeach; ?><?php else: ?><div class="section__title product-empty"><i class="fas fa-box-open product-empty__icon"></i><p class="section__title-text">Aún no hay productos registrados.</p></div><?php endif; ?>
